const fs = require("fs");
const path = require("path");
const poseidonContract = require(path.join(
  __dirname,
  "../node_modules/circomlibjs/src/poseidon_gencontract.js"
));

const abi = poseidonContract.generateABI(1);
const bytecode = poseidonContract.createCode(1);

const iface = `// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

/// @notice Interface for Poseidon1 hasher contract generated by circomlibjs.
/// @dev Expects ABI: poseidon(uint256[1]) returns (uint256)
interface IPoseidon1 {
    function poseidon(uint256[1] calldata input) external pure returns (uint256);
}
`;

const sol = `// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

/// @notice Poseidon hash contract (1 input), generated from circomlibjs.
/// @dev This contract's constructor returns the runtime extracted from the circomlibjs initcode.
///      The deployed runtime implements a pure function that can be called via staticcall.
contract Poseidon1 {
    constructor() {
        bytes memory code = hex"${bytecode.slice(2)}";
        assembly {
            let dataPtr := add(code, 0x20)
            let runtimePtr := add(dataPtr, 12)
            let runtimeLen := sub(mload(code), 12)
            return(runtimePtr, runtimeLen)
        }
    }
}
`;

fs.mkdirSync(path.join(__dirname, "../src/poseidon"), { recursive: true });
fs.writeFileSync(path.join(__dirname, "../src/poseidon/IPoseidon1.sol"), iface);
fs.writeFileSync(path.join(__dirname, "../src/poseidon/Poseidon1.sol"), sol);

console.log("Generated:");
console.log(" - src/poseidon/IPoseidon1.sol");
console.log(" - src/poseidon/Poseidon1.sol");
console.log("\nABI:");
console.log(JSON.stringify(abi, null, 2));
